let currentLang = 'es'
const SECTIONS = ['home', 'servicios', 'quienes-somos', 'contacto']

function setActiveLink(activeEl, allLinks) {
  allLinks.forEach(link => link.classList.remove('nav-link--active'))
  activeEl.classList.add('nav-link--active')
}

function initNavigation() {
  const allLinks = Array.from(document.querySelectorAll('nav a[data-section]'))

  allLinks.forEach(link => {
    link.addEventListener('click', event => {
      event.preventDefault()
      setActiveLink(link, allLinks)
      scrollToSection(link.dataset.section)
    })
  })
}

function scrollToSection(sectionId) {
  const target = document.getElementById(sectionId)
  if (!target) return
  target.scrollIntoView({ behavior: 'smooth', block: 'start' })
}

function findLinkBySection(sectionId, allLinks) {
  return allLinks.find(link => link.dataset.section === sectionId) || null
}

function initScrollSpy() {
  const sections = Array.from(document.querySelectorAll('section[id]'))
  const allLinks = Array.from(document.querySelectorAll('nav a[data-section]'))

  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return
      const matchingLink = findLinkBySection(entry.target.id, allLinks)
      if (matchingLink) setActiveLink(matchingLink, allLinks)
    })
  }, { threshold: 0.4 })

  sections.forEach(section => observer.observe(section))
}

function applyLangToElement(el, lang) {
  const text = el.dataset[lang]
  if (text !== undefined) el.textContent = text
}

function initLangToggle() {
  const toggleBtn = document.querySelector('[data-lang-toggle]')
  if (!toggleBtn) return

  const translatableEls = Array.from(document.querySelectorAll('[data-es][data-en]'))

  toggleBtn.addEventListener('click', () => {
    currentLang = currentLang === 'es' ? 'en' : 'es'
    translatableEls.forEach(el => applyLangToElement(el, currentLang))
    toggleBtn.textContent = currentLang === 'es' ? 'EN' : 'ES'
    document.documentElement.setAttribute('lang', currentLang)
  })
}

function initAnimations() {
  const animatedEls = Array.from(document.querySelectorAll('[data-animate]'))

  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return
      entry.target.classList.add('is-visible')
      observer.unobserve(entry.target)
    })
  }, { threshold: 0.15 })

  animatedEls.forEach(el => observer.observe(el))
}

function setInitialActiveLink() {
  const allLinks = Array.from(document.querySelectorAll('nav a[data-section]'))
  if (allLinks.length === 0) return
  const firstLink = allLinks.find(link => link.dataset.section === SECTIONS[0])
  if (firstLink) setActiveLink(firstLink, allLinks)
}

document.addEventListener('DOMContentLoaded', () => {
  setInitialActiveLink()
  initNavigation()
  initScrollSpy()
  initLangToggle()
  initAnimations()
})

const FORMSPREE_ENDPOINT = 'https://formspree.io/f/XXXXXXXX';

function isNotEmpty(value) {
  return value.trim().length > 0;
}

function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function isValidPhone(value) {
  if (value.trim() === '') return true;
  return /^[\d\s\+\-\(\)]{7,15}$/.test(value);
}

function isNotTooLong(value, max) {
  return value.trim().length <= max;
}

function sanitize(value) {
  return value.trim();
}

function showFieldError(fieldId, message) {
  const el = document.getElementById(fieldId + '-error');
  if (!el) return;
  el.textContent = message;
}

function clearAllErrors(formElement) {
  formElement.querySelectorAll('[id$="-error"]').forEach(function (el) {
    el.textContent = '';
  });
}

function validateForm(data) {
  const errors = {};

  if (!isNotEmpty(data.name)) {
    errors.name = 'El nombre no puede estar vacío.';
  } else if (!isNotTooLong(data.name, 100)) {
    errors.name = 'El nombre no puede superar los 100 caracteres.';
  }

  if (!isNotEmpty(data.email)) {
    errors.email = 'El correo electrónico no puede estar vacío.';
  } else if (!isValidEmail(data.email)) {
    errors.email = 'Ingresa un correo electrónico válido.';
  }

  if (!isValidPhone(data.phone)) {
    errors.phone = 'Ingresa un número de teléfono válido.';
  }

  if (!isNotEmpty(data.message)) {
    errors.message = 'El mensaje no puede estar vacío.';
  } else if (!isNotTooLong(data.message, 1000)) {
    errors.message = 'El mensaje no puede superar los 1000 caracteres.';
  }

  return {
    isValid: Object.keys(errors).length === 0,
    errors: errors
  };
}

function setLoadingState(submitButton, isLoading) {
  if (isLoading === true) {
    submitButton.disabled = true;
    submitButton.textContent = 'Enviando...';
  } else {
    submitButton.disabled = false;
    submitButton.textContent = 'Enviar mensaje';
  }
}

async function handleSubmit(event) {
  event.preventDefault();

  const form = event.target;
  const submitButton = form.querySelector('[type="submit"]');

  clearAllErrors(form);

  const data = {
    name: sanitize(form.querySelector('#contact-name').value),
    email: sanitize(form.querySelector('#contact-email').value),
    phone: sanitize(form.querySelector('#contact-phone').value),
    message: sanitize(form.querySelector('#contact-message').value)
  };

  const validation = validateForm(data);

  if (!validation.isValid) {
    Object.keys(validation.errors).forEach(function (field) {
      showFieldError('contact-' + field, validation.errors[field]);
    });
    return;
  }

  setLoadingState(submitButton, true);

  try {
    const response = await fetch(FORMSPREE_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify(data)
    });

    if (response.ok) {
      const successEl = document.getElementById('contact-success');
      if (successEl) {
        successEl.textContent = 'Tu mensaje fue enviado correctamente. ¡Nos pondremos en contacto pronto!';
      }
      form.reset();
    } else {
      const errorEl = document.getElementById('contact-form-error');
      if (errorEl) {
        errorEl.textContent = 'Hubo un problema al enviar el mensaje. Por favor, intenta nuevamente.';
      }
    }
  } catch (networkError) {
    const errorEl = document.getElementById('contact-form-error');
    if (errorEl) {
      errorEl.textContent = 'No se pudo conectar con el servidor. Verifica tu conexión e intenta nuevamente.';
    }
  } finally {
    setLoadingState(submitButton, false);
  }
}

function initContactForm() {
  const form = document.getElementById('contact-form');
  if (!form) return;
  form.addEventListener('submit', handleSubmit);
}

document.addEventListener('DOMContentLoaded', initContactForm);
